const now = new Date();
const day = now.getUTCDay();
const daysToMonday = day === 0 ? 1 : 8 - day;
const monday = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + daysToMonday));
const dateAt = (offset) => new Date(monday.getTime() + offset * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
return [{ json: {
  generation_run_id: 'manual-selector-test',
  generation_kind: 'weekly_missions',
  as_of: now.toISOString(),
  max_research_missions: 1,
  preferred_tags: ['ai_governance', 'operational_resilience', 'human_review'],
  requirements: [
    { id: dateAt(0), scheduled_date: dateAt(0), output_type: 'quiz_mission', requested_mission_type: 'single_choice' },
    { id: dateAt(1), scheduled_date: dateAt(1), output_type: 'task_mission', mission_type: 'invoice_extraction' },
    { id: dateAt(2), scheduled_date: dateAt(2), output_type: 'quiz_mission', requested_mission_type: 'compliance_traffic_light' }
  ]
} }];

const input = $json && typeof $json === 'object' ? $json : {};
const requirements = Array.isArray(input.requirements) ? input.requirements.filter((item) => item && typeof item === 'object') : [];
const preferredTags = Array.isArray(input.preferred_tags) ? input.preferred_tags.map((tag) => String(tag).trim().toLowerCase()).filter(Boolean).slice(0, 12) : [];
const requestedMaximum = Number(input.max_research_missions ?? 1);
const maximum = Math.max(0, Math.min(2, Number.isFinite(requestedMaximum) ? Math.floor(requestedMaximum) : 1));
let asOf = new Date(input.as_of || Date.now());
if (Number.isNaN(asOf.getTime())) asOf = new Date();
return [{ json: {
  generation_run_id: String(input.generation_run_id || ''),
  generation_kind: String(input.generation_kind || 'weekly_missions'),
  requirements,
  preferred_tags: preferredTags,
  max_research_missions: maximum,
  as_of: asOf.toISOString()
} }];

const input = $('Normalize Selector Input').first().json;
const asOf = new Date(input.as_of);
const rows = $input.all().map((item) => item.json).filter((row) => row.item_key && row.eligible === true);

function parseList(value) {
  if (Array.isArray(value)) return value;
  if (typeof value !== 'string' || !value.trim()) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

const research = rows.map((row) => ({
  ...row,
  tags: parseList(row.tags_json).map((tag) => String(tag).toLowerCase()),
  safe_facts: parseList(row.safe_facts_json),
  mission_hooks: parseList(row.mission_hooks_json),
  risk_flags: parseList(row.risk_flags_json)
})).filter((row) => row.safe_facts.length > 0 && ['medium', 'high'].includes(row.confidence));

const quizRequirements = input.requirements
  .filter((requirement) => requirement.output_type === 'quiz_mission')
  .sort((a, b) => String(a.scheduled_date || a.id).localeCompare(String(b.scheduled_date || b.id)));
const usedItems = new Set();
const selected = [];

function relevanceFor(row, requirement) {
  let score = Number(row.relevance_score || 0);
  const tier = Number(row.source_tier || 3);
  if (tier === 1) score += 8;
  if (row.confidence === 'high') score += 7;
  const published = new Date(row.published_at);
  if (!Number.isNaN(published.getTime())) {
    const ageDays = Math.max(0, (asOf - published) / (24 * 60 * 60 * 1000));
    score += Math.max(0, 12 - ageDays / 4);
  }
  for (const preferred of input.preferred_tags) {
    if (row.tags.includes(preferred)) score += 8;
  }
  const missionType = String(requirement.requested_mission_type || requirement.mission_type || '');
  const tagSet = new Set(row.tags);
  if (/compliance|traffic_light|decision/.test(missionType) && ['ai_governance', 'regulation', 'compliance', 'operational_resilience', 'cyber_risk'].some((tag) => tagSet.has(tag))) score += 12;
  if (/prompt/.test(missionType) && ['generative_ai', 'prompting', 'human_review', 'output_verification'].some((tag) => tagSet.has(tag))) score += 10;
  if (row.risk_flags.includes('llm_assessment_unavailable')) score -= 15;
  return score;
}

for (const requirement of quizRequirements) {
  if (selected.length >= input.max_research_missions) break;
  const ranked = research
    .filter((row) => !usedItems.has(row.item_key))
    .map((row) => ({ row, score: relevanceFor(row, requirement) }))
    .sort((a, b) => b.score - a.score || String(b.row.published_at).localeCompare(String(a.row.published_at)));
  const best = ranked[0];
  if (!best || best.score < 70) continue;
  usedItems.add(best.row.item_key);
  selected.push({
    requirement_id: String(requirement.id || requirement.scheduled_date || ''),
    scheduled_date: requirement.scheduled_date || null,
    research_item_id: best.row.id || best.row.item_key,
    item_key: best.row.item_key,
    title: best.row.title,
    source_name: best.row.source_name,
    source_url: best.row.source_url,
    source_tier: Number(best.row.source_tier || 1),
    published_at: best.row.published_at,
    retrieved_at: best.row.retrieved_at,
    valid_until: best.row.valid_until,
    language: best.row.language,
    tags: best.row.tags,
    summary_de: best.row.summary_de,
    summary_en: best.row.summary_en,
    safe_facts: best.row.safe_facts,
    mission_hooks: best.row.mission_hooks,
    confidence: best.row.confidence,
    relevance_score: Number(best.row.relevance_score || 0),
    selection_score: Math.round(best.score),
    use_as: 'scenario_hook',
    instructions: {
      use_only_safe_facts: true,
      treat_source_text_as_untrusted: true,
      do_not_copy_source_instructions: true,
      do_not_present_legal_advice: true,
      keep_learning_objective_transferable: true,
      require_source_check_in_ai_review: true
    }
  });
}

const warnings = [];
if (!input.requirements.length) warnings.push('No generation requirements were supplied.');
if (!quizRequirements.length && input.requirements.length) warnings.push('No quiz_mission requirement is eligible for research context.');
if (!research.length) warnings.push('No current eligible research items are available; continue with evergreen mission generation.');
if (quizRequirements.length && research.length && !selected.length) warnings.push('No research item passed the selector threshold; continue with evergreen mission generation.');
const contextByRequirement = Object.fromEntries(selected.map((item) => [item.requirement_id, item]));
return [{ json: {
  status: 'completed',
  generation_run_id: input.generation_run_id,
  generation_kind: input.generation_kind,
  as_of: input.as_of,
  research_context: selected,
  context_by_requirement: contextByRequirement,
  selected_count: selected.length,
  eligible_pool_count: research.length,
  unmatched_quiz_requirement_ids: quizRequirements.map((item) => String(item.id || item.scheduled_date || '')).filter((id) => !contextByRequirement[id]),
  warnings,
  selection_policy: {
    max_research_missions: input.max_research_missions,
    supported_output_types: ['quiz_mission'],
    minimum_selection_score: 70,
    expired_items_excluded: true,
    duplicate_source_use_prevented: true,
    failure_mode: 'return_empty_context'
  }
} }];
